@pytest.mark.parametrize(
    "project_relative",
    [
        "lcls-plc-kfe-gmd-vac/plc/plc-kfe-gmd-vac/plc-kfe-gmd-vac.tsproj",
        "lcls-plc-lfe-motion/plc-lfe-motion/plc-lfe-motion.tsproj",
    ],
    ids=("kfe-gmd-vac", "lfe-motion"),
)
def test_template_generates_ethercat_db_and_access_config(
    project_relative, tmp_path, capsys
):
    project_filename = TEMPLATES.parent / "projects" / project_relative
    project = pytmc.parser.parse(project_filename)
    plc = list(project.plcs)[0]

    template_main(
        [str(project_filename)],
        templates=str(TEMPLATES / "ethercat_state_generation.txt"),
        macros={
            "plc_name": plc.name,
            "plc_database_path": str(tmp_path / f"{plc.filename.stem}.db"),
            "prefix": "PREFIX:",
            "macro_substitutions": {
                "PREFIX": "PREFIX:",
                "IOC": plc.filename.stem,
                "IOCNAME": plc.filename.stem,
            },
            "db_parameters": "IOCNAME=$(IOC),IOC=$(IOC)",
            "ethercat_state_scan_seconds": "3",
        },
    )

    output = capsys.readouterr().out
    ethercat_database_path = tmp_path / f"{plc.filename.stem}_EtherCAT.db"
    assert f'dbLoadRecords("{ethercat_database_path}"' in output
    terminal = pytmc.ethercat.get_ethercat_terminals(project)[0]
    ethercat_database = ethercat_database_path.read_text()
    assert (
        f'record(longin, "$(PREFIX)ECAT:{terminal.port}:StateRaw")'
        in ethercat_database
    )
    assert f'field(DESC, "{terminal.name}")' in ethercat_database
    old_terminal_pv = f"$(PREFIX)ECAT:{terminal.port}:{terminal.pv_component}"
    assert old_terminal_pv not in ethercat_database
    assert "ECAT_STATE_SCAN_SECONDS=3" in output
    access_config = tmp_path / f"{plc.filename.stem}_ethercat_state_access.cmd"
    access_text = access_config.read_text()
    assert f"# Port {terminal.port}: {terminal.name}" in access_text
    assert (
        f'# epicsEnvSet("ECAT_ASG_{terminal.port}_{terminal.access_component}", '
        '"DEFAULT")'
    ) in access_text


def test_template_skips_ethercat_files_when_database_macros_are_not_forwarded(
    tmp_path,
):
    project_filename = (
        TEMPLATES.parent
        / "projects"
        / "lcls-plc-kfe-gmd-vac"
        / "plc"
        / "plc-kfe-gmd-vac"
        / "plc-kfe-gmd-vac.tsproj"
    )
    project = pytmc.parser.parse(project_filename)
    plc = list(project.plcs)[0]
    template_without_forwarded_macros = (
        tmp_path / "template_without_forwarded_macros.st.cmd.template"
    )
    template_without_forwarded_macros.write_text(
        "{% set project, plc = get_plc_by_name(projects, plc_name) %}\n"
        "{% set generated_files, _ = generate_records(\n"
        "    plc, path=plc_database_path, write_archive_file=False,\n"
        "    allow_errors=True,\n"
        ") %}\n"
        "{{ generated_files | join(',') }}"
    )

    template_main(
        [str(project_filename)],
        templates=str(template_without_forwarded_macros),
        macros={
            "plc_name": plc.name,
            "plc_database_path": str(tmp_path / f"{plc.filename.stem}.db"),
            "prefix": f"PLC:{plc.name}:",
            "ads_ioc_name": f"ioc-{plc.name}",
            "db_parameters": (
                f"PREFIX=PLC:{plc.name}:,IOCNAME=$(IOC),IOC=$(IOC)"
            ),
        },
    )

    assert not (tmp_path / f"{plc.filename.stem}_EtherCAT.db").exists()
    assert not (
        tmp_path / f"{plc.filename.stem}_ethercat_state_access.cmd"
    ).exists()


