@pytest.mark.parametrize(
    "argument, input_filename, output_filename",
    [
        pytest.param(
            "a", "a", "",
            id="template-file-to-stdout"
        ),
        pytest.param(
            "-", "-", "",
            id="stdin-to-stdout",
        ),
        pytest.param(
            "a:b", "a", "b",
        ),
        pytest.param(
            "C:/a/b/c.def:D:/d/e/f.ghi",
            "C:/a/b/c.def",
            "D:/d/e/f.ghi",
        ),
        pytest.param(
            "//a/b/c.def:D:/d/e/f.ghi",
            "//a/b/c.def",
            "D:/d/e/f.ghi",
        ),
        pytest.param(
            "/tmp/:messed:up:filename:/tmp/a/b:c:d",
            "/tmp/:messed:up:filename",
            "/tmp/a/b:c:d",
        ),
        pytest.param(
            "-:output_fn",
            "-",
            "output_fn",
        ),
        pytest.param(
            "C:/Repos/ads-ioc/R2.1.3/iocBoot/templates/st.cmd.template:st.cmd",
            "C:/Repos/ads-ioc/R2.1.3/iocBoot/templates/st.cmd.template",
            "st.cmd",
            id="windows-drive-letter-forward-slash-single-real-delimiter",
        ),
        pytest.param(
            "C:\\Repos\\ads-ioc\\R2.1.3\\iocBoot\\templates\\st.cmd.template:st.cmd",
            "C:\\Repos\\ads-ioc\\R2.1.3\\iocBoot\\templates\\st.cmd.template",
            "st.cmd",
            id="windows-drive-letter-backslash-single-real-delimiter",
        ),
    ],
)
def test_filename_split(
    argument: str,
    input_filename: str,
    output_filename: str,
    monkeypatch,
):

    def exists(fn: str) -> bool:
        if fn in {"-", ""}:
            return False
        print("Exists?", fn, fn in {input_filename, output_filename})
        return fn in {input_filename, output_filename}

    monkeypatch.setattr(os.path, "exists", exists)
    inp, outp = pytmc.bin.template.split_input_output(argument)
    assert inp == input_filename
    assert outp == output_filename


@pytest.mark.parametrize(
    "argument, input_filename, output_filename",
    [
        pytest.param(
            "C:/Repos/ads-ioc/R2.1.3/iocBoot/templates/st.cmd.template:st.cmd",
            "C:/Repos/ads-ioc/R2.1.3/iocBoot/templates/st.cmd.template",
            "st.cmd",
            id="forward-slash",
        ),
        pytest.param(
            "C:\\Repos\\ads-ioc\\R2.1.3\\iocBoot\\templates\\st.cmd.template:st.cmd",
            "C:\\Repos\\ads-ioc\\R2.1.3\\iocBoot\\templates\\st.cmd.template",
            "st.cmd",
            id="backslash",
        ),
    ],
)
def test_filename_split_windows_drive_letter_ignores_filesystem_state(
    argument: str,
    input_filename: str,
    output_filename: str,
    monkeypatch,
):
    """A drive letter followed by a single real delimiter must split
    correctly even when nothing exists on disk -- the split point comes
    from the argument's shape, not from a filesystem lookup."""

    monkeypatch.setattr(os.path, "exists", lambda fn: False)
    inp, outp = pytmc.bin.template.split_input_output(argument)
    assert inp == input_filename
    assert outp == output_filename
